import { test, expect } from '@playwright/test';

test.describe('Password Strength Indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/password-change');
  });

  test('should display password strength indicator with weak password', async ({ page }) => {
    // Set up intercept for password input
    await page.route('**/api/password-change/set-password', (route) => {
      route.continue();
    });

    // Set up intercept for password strength response
    await page.route('**/api/password-strength', (route) => {
      route.continue();
    });

    // Set up intercept for success response
    await page.route('**/api/password-change/set-password/success', (route) => {
      route.continue();
    });

    // Set up intercept for error response
    await page.route('**/api/password-change/set-password/error', (route) => {
      route.abort('failed');
    });

    // Set up intercept for loading state
    await page.route('**/api/password-change/set-password/loading', (route) => {
      route.abort('failed');
    });

    // Get password input by role
    const passwordInput = page.getByRole('textbox', { name: /password/i });
    await expect(passwordInput).toBeVisible();

    // Set weak password
    await passwordInput.fill('123456');

    // Get password strength indicator by role
    const strengthIndicator = page.getByRole('status', { name: /weak/i });
    await expect(strengthIndicator).toBeVisible();

    // Verify indicator text
    await expect(strengthIndicator).toContainText('Weak');

    // Verify password strength icon
    const strengthIcon = page.getByTestId('password-strength-icon');
    await expect(strengthIcon).toBeVisible();

    // Verify error message
    const errorMessage = page.getByText(/Password must be at least 8 characters long/i);
    await expect(errorMessage).toBeVisible();

    // Verify success message
    const successMessage = page.getByText(/Password set successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Verify password input is still visible
    await expect(passwordInput).toBeVisible();
  });

